  assign tx_ready_o         = wr_en_i;

  // and the last_read bit to indicate whether
  // it is the last in a series.
  logic        [8:0] rx_buf_q;
  logic        [8:0] rx_buf_d;
  logic              rx_buf_valid_q;
  logic              rx_buf_valid_d;

  `ASSERT(SpeedValid, speed_i != RsvdSpd, clk_i, rst_ni)

  assign next_bits  = full_cyc_i ? sd_i : sd_i_q;
  assign sr_shifted = (speed_i == Standard) ? {sr_q[6:0], next_bits[1]} :
                      (speed_i == Dual)     ? {sr_q[5:0], next_bits[1:0]} :
                      (speed_i == Quad)     ? {sr_q[3:0], next_bits[3:0]} :
                      8'h00;

  assign sd_o       = (speed_i == Standard) ? {3'b000, sr_q[7]}   :
                      (speed_i == Dual)     ? {2'b00,  sr_q[7:6]} :
                      (speed_i == Quad)     ? {sr_q[7:4]} :
                      4'h0;

  // Buffer the rx_data outputs to simplify three-way flow control
  // between fsm, shift reg and byte_merge.
  assign rd_ready_o             = ~rx_buf_valid_q | (rx_valid_o & rx_ready_i);
  assign rx_valid_o             = rx_buf_valid_q;

  assign rx_buf_d               = sw_rst_i                ? 9'h0 :
                                  (rd_en_i && rd_ready_o) ? {last_read_i, sr_shifted} :
                                  rx_buf_q;

  assign rx_buf_valid_d         = sw_rst_i                  ? 1'b0 :
                                  (rd_en_i && rd_ready_o)   ? 1'b1 :
                                  (rx_valid_o & rx_ready_i) ? 1'b0 :
                                  rx_buf_valid_q;

  assign sd_i_d                 = sw_rst_i    ? 4'b0 :
                                  sample_en_i ? sd_i :
                                  sd_i_q;

  assign {rx_last_o, rx_data_o} = rx_buf_q;

  // tx_data cannot be buffered, because of the
  // need to transmit tx_flush as we fetch the
  // last-needed byte.
  assign wr_ready_o         = tx_valid_i;
  assign tx_ready_o         = wr_en_i;
  assign tx_flush_o         = last_write_i;

  assign sr_d = sw_rst_i               ? 8'h0 :
                (wr_en_i & wr_ready_o) ? tx_data_i :
                shift_en_i             ? sr_shifted :
                sr_q;

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      sd_i_q <= 4'h0;
      sr_q <= 8'h0;
      rx_buf_valid_q <= 1'b0;
      rx_buf_q <= 9'h0;
    end else begin
      sd_i_q <= sd_i_d;
      sr_q <= sr_d;
      rx_buf_valid_q <= rx_buf_valid_d;
      rx_buf_q <= rx_buf_d;
    end
  end

endmodule : spi_host_shift_register

// Instead, use a CSB-clocked toggle and detect the much slower-changing
// toggles, making use of CSB's low duty cycle.
//
// In addition, this module filters CSB "cycles" without SPI clocks.
// The sck_pulse_en_i input allows further filtering of CSB-triggered pulses.
// For example, this can be used to trigger a pulse only when there is a new
// uploaded command.

module spid_csb_sync (
  input clk_i,
  input rst_ni,
  input sck_i,
  input sck_pulse_en_i,
  input csb_i,
  output csb_deasserted_pulse_o
);

  logic sck_toggle, csb_toggle, sys_toggle, sys_toggle_last;

  // CSB and SCK have setup / hold relationships for SPI flash devices. Only
  // change counts on CSB posedge if there is at least one SCK cycle.
  always_ff @(posedge sck_i or negedge rst_ni) begin
    if (!rst_ni) begin
      sck_toggle <= 1'b0;
    end else begin
      if (sck_pulse_en_i) begin
        sck_toggle <= ~csb_toggle;
      end
    end
  end

  // Signal CSB de-assertion with a change in count, but only do it if the
  // change originated from the SCK domain.
  always_ff @(posedge csb_i or negedge rst_ni) begin
    if (!rst_ni) begin
      csb_toggle <= 1'b0;
    end else begin
      csb_toggle <= sck_toggle;
    end
  end

  // clk_i is asynchronous to CSB/SCK, so use a synchronizer.
  prim_flop_2sync #(
    .Width     (1)
  ) u_count_sync (
    .clk_i,
    .rst_ni,
    .d_i       (csb_toggle),
    .q_o       (sys_toggle)
  );

  // sys_toggle_last is used to generate the pulse on differences.
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      sys_toggle_last <= 1'b0;
    end else begin
      sys_toggle_last <= sys_toggle;
    end
  end

  assign csb_deasserted_pulse_o = (sys_toggle != sys_toggle_last);
endmodule : spid_csb_sync

